import { mountCrapsQuickEntry } from './craps-quick-entry.js';

// Pick once per page visit. Polling, purchases and cabinet view changes must
// never move a different game under the pointer.
export function mountGameFeature(previewOptions, openGame) {
  const games = document.createElement('div');
  games.className = 'concept-games';
  games.setAttribute('role', 'group');
  const cards = `
    <span class="site-feature-cards" aria-hidden="true">
      <span class="site-feature-card"><img src="/badges-circular/crypto_06_ethereum_green.svg" alt=""></span>
      <span class="site-feature-card"><img src="/badges-circular/cards_07_ace_wild.svg" alt=""></span>
      <span class="site-feature-card"><img src="/badges-circular/dice_05_6_gold.svg" alt=""></span>
    </span>`;
  for (const [kind, label, target, art] of [
    ['degenerette', 'Degenerette', 'app-degenerette-panel', './art/degenerette-compact-to-win-v6.png'],
    ['craps', 'Craps Autobattle', 'app-craps-entry', '/app/assets/craps/craps-autobattle-integrated-swords-v9-w560.webp'],
  ]) {
    const cell = document.createElement('div');
    cell.className = `concept-game site-${kind}-cell`;
    cell.dataset.feature = kind;
    cell.hidden = true;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'site-game-art';
    button.setAttribute('aria-label', `Play ${label}`);
    button.innerHTML = (kind === 'degenerette' ? cards
      : '<span class="site-feature-dice" aria-hidden="true"><img src="/app/two-widget-hub/art/feature-craps-dice.svg" alt=""></span>')
      + `<img class="site-feature-logo" src="${new URL(art, import.meta.url).href}" alt="">`
      + (kind === 'degenerette' ? '<span class="site-feature-play">PLAY NOW <span aria-hidden="true">→</span></span>' : '');
    button.addEventListener('click', () => openGame(target));
    cell.append(button);
    games.append(cell);
  }

  const randomFeature = Math.random() < 0.5 ? 'degenerette' : 'craps';
  let crapsMounted = false;
  const choose = (mode) => {
    const selected = ['degenerette', 'craps'].includes(mode) ? mode : randomFeature;
    games.dataset.feature = selected;
    games.setAttribute('aria-label', selected === 'craps' ? 'Featured game: Craps Autobattle' : 'Featured game: Degenerette');
    for (const cell of games.children) cell.hidden = cell.dataset.feature !== selected;
    if (selected === 'craps' && !crapsMounted) {
      crapsMounted = true;
      mountCrapsQuickEntry(games.querySelector('.site-craps-cell'));
    }
  };

  // Existing design controls let both compositions be reviewed without reloads.
  const label = document.createElement('label');
  label.textContent = 'Featured game';
  const select = document.createElement('select');
  select.setAttribute('aria-label', 'Featured game');
  for (const [value, text] of [['random', 'Random each visit'], ['craps', 'Craps Autobattle'], ['degenerette', 'Degenerette']]) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = text;
    select.append(option);
  }
  const requested = new URLSearchParams(location.search).get('feature');
  select.value = ['craps', 'degenerette'].includes(requested) ? requested : 'random';
  select.addEventListener('change', () => {
    choose(select.value);
    const url = new URL(location.href);
    if (select.value === 'random') url.searchParams.delete('feature');
    else url.searchParams.set('feature', select.value);
    history.replaceState(null, '', url);
  });
  label.append(select);
  previewOptions.append(label);
  choose(select.value);
  return games;
}
